fn fibonacci(n: usize) -> Vec<i32> {
    // Precondition: n >= 2 and for all i < n, F(i) fits in i32.
    let mut fibs = Vec::with_capacity(n);
    fibs.push(0); // F(0)
    fibs.push(1); // F(1)

    for i in 2..n {
        // Since the problem guarantees values fit in i32, no overflow checking needed here.
        let next = fibs[i - 1] + fibs[i - 2];
        fibs.push(next);
    }

    fibs
}